function OverseaContinuousRechargeDialog:InitData()
    self.allVos = CfUtils.GetCf(AutoIds.IdSetting3088, "LimitTimeOfferVo", true)
end

function OverseaContinuousRechargeDialog:RequestShow()
    GameUtils.Request(Interfaces.OverseaSpecialGift,{},function(request,response)
        if  checkInt(response.errCode) == 0  then
            self.data = response.data.specialGift
            if playerComponent then
                local playerDojo = playerComponent.playerDojo
                if playerDojo then
                    if isSet(self.data,"signDayNumber") and isSet(self.data,"receiveId") then
                        playerDojo.overseaSpecialGift = { signDayNumber = self.data.signDayNumber, receiveId = self.data.receiveId }
                    end
                    local IsHavePay = self:IsHavePay(playerDojo)
                    self:SetButtonState(IsHavePay)
                end
            end
            self:RefreshCellShow()
            local windowsPriceId = CfUtils.GetWindowsPriceId(self.data)
            CfUtils.FillText(self.TextBuy, string.format("<size=40>%s</size>%s",CfUtils.GetCurrerySymbol(), CfUtils.GetPrice(windowsPriceId ,self.data.channelProductId)))
            CfUtils.FillText(self.TxtOriginalCost,CfUtils.GetDisplayPrice(self.data.originalPrice))
        end
    end )
end

function OverseaContinuousRechargeDialog:RefreshCellShow()
    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#self.allVos, Bind(self, self.OnRefreshCellIndex))
        else
            GameUtils.ReloadData(self.ScrollView, #self.allVos)
        end
    end
end

function OverseaContinuousRechargeDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.allVos then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
    tableCellEnv:SetCallBackAndIndex(Bind(self,self.OnDrawRewardClick),index + 1)
    tableCellEnv:RefreshShow(self.allVos[index + 1])
    local luaIndex = index + 1
    if not self.cellAnimMap_[luaIndex] then
        self.cellAnimMap_[luaIndex] = true
        tableCellEnv:PlayAnimByEnter(index)
    else
        tableCellEnv:PlayAnimByShowed()
    end
    return cell
end

function OverseaContinuousRechargeDialog:OnDrawRewardClick(index)
    GameUtils.Request(Interfaces.OverseaDrawSpecialReward,{day = index},function(request,response)
        if checkInt(response.errCode) == 0 then
            local responseData = response.data
            local playerDojo = playerComponent.playerDojo
            if playerDojo then
                playerDojo.overseaSpecialGift.receiveId[tostring(index)] = index
            end
            self:RefreshCellShow()
            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
        end
    end)
end

function OverseaContinuousRechargeDialog:SetButtonState(state)
    KTool.SetActive(self.BtnHaveBuy.gameObject,state)
    KTool.SetActive(self.BtnBuy.gameObject,not state)
end

function OverseaContinuousRechargeDialog:IsHavePay(playerDojo)
    if not isNull(playerDojo.overseaSpecialGift) and isSet(playerDojo.overseaSpecialGift,"signDayNumber") then
        return true
    end
    return false
end


return OverseaContinuousRechargeDialog